import{dernierePage}from"./chunk-PYO3OIRW.js";import{chapitresPublies,matieresOuvertes}from"./chunk-VAMJG6AG.js";import{SITE,serveur}from"./chunk-3DLLZPW5.js";import{lien}from"./chunk-MENTKLMX.js";import{echap}from"./chunk-7TQW5JOI.js";var lienConnexion=()=>serveur()||!SITE.adresse?lien("connexion.html"):SITE.adresse.replace(/\/+$/,"")+"/connexion.html";function tete(body,surtitre,titre,chapeau){let t=body.querySelector(".accueil-tete .in");t&&(t.innerHTML='<span class="surtitre">'+echap(surtitre)+"</span><h1>"+echap(titre)+"</h1>"+(chapeau?"<p>"+echap(chapeau)+"</p>":""))}var carte=(surtitre,titre,corps,extra)=>'<section class="carte'+(extra?" "+extra:"")+'"><span class="surtitre">'+surtitre+"</span><h2>"+titre+"</h2>"+corps+"</section>",liste=l=>'<ul class="transparence-liste">'+l.map(([o,t])=>"<li>"+o+"<span>"+t+"</span></li>").join("")+"</ul>",OUI='<span class="oui" aria-hidden="true">✓</span>',NON='<span class="non" aria-hidden="true">✗</span>',oui=t=>[OUI,t],non=t=>[NON,'<span class="sr">Non : </span>'+t],COMPTES_DU_TEST="Pendant le test, les comptes s'ouvrent sur invitation : avec le code d'inscription que donne le professeur qui mène le test. Un élève de moins de 15 ans invite ensuite un parent, dont l'accord est demandé avant que sa progression soit enregistrée en ligne.",SANS_COMPTE="Sans compte, tout le reste du site est ouvert : les cours, les labos, les jeux et les quiz. Ta progression reste alors dans ce navigateur, et nulle part ailleurs.";function seConnecter(texte){return'<p class="ligne"><a class="btn" href="'+lienConnexion()+'">'+(texte||"Se connecter")+"</a>"+(serveur()?"":'<span class="discret">Les comptes vivent sur '+echap(hote())+".</span>")+"</p>"}var hote=()=>{try{return new URL(SITE.adresse).host}catch{return"le site en ligne"}},POUR_QUI=[["Élève","Apprendre à trouver seul","Des cours écrits par des professeurs, des labos où tu manipules, des jeux et des quiz pour t'entraîner, des exercices corrigés. Le tuteur te pose une question, puis te donne un indice, jamais la réponse. Ton bureau garde ta progression, comparée à toi-même, jamais aux autres."],["Parent","Suivre sans surveiller","Le temps de travail de ton enfant, sa progression, ses échéances, et tout le carnet de ses professeurs, en lecture. Ni ses réponses, ni ses brouillons, ni ses échanges avec le tuteur. Tu peux couper l'IA du tuteur."],["Professeur","Proposer, puis laisser chercher","Un lien de classe pour tes élèves ; un exercice, une partie du cours, une échéance ou un devoir composé dans la banque d’exercices, envoyés dans leur carnet. Tu vois ce qu’ils réussissent seuls, sans note ni classement."]],JAMAIS=["faire tes devoirs à ta place : le tuteur pose une question, puis donne un indice, puis un exemple voisin — jamais la solution ;","te noter, te classer ou te comparer aux autres : le seul indicateur, c’est ce que tu réussis seul, comparé à toi-même ;","montrer une publicité, vendre ou céder tes données : elles servent le site, et rien d’autre ;","ouvrir une messagerie entre utilisateurs ;","cacher l’IA : elle est toujours signalée, et on peut la couper."];function presenterAccueil(body,m){tete(body,SITE.nom,SITE.accroche||"",SITE.sousTitre||"");let d=dernierePage(),reprendre=d?'<a class="reprendre" href="'+lien(d.url)+'"><small>Reprendre où tu en étais</small><strong>'+echap(d.titre)+"</strong><span>"+echap(d.sous||"")+" · gardé dans ce navigateur</span></a>":"",matieres=matieresOuvertes().map(mm=>{let n=chapitresPublies(mm).length;return'<a class="matiere-mini" data-couleur="'+echap(mm.couleur||"neutre")+'" href="'+lien("matiere.html?m="+encodeURIComponent(mm.id))+'"><strong>'+echap(mm.nom)+'</strong><span class="discret">'+n+" chapitre"+(n>1?"s":"")+" en ligne</span></a>"}).join("");m.innerHTML='<div class="pile ecart-6 presentation">'+(reprendre?'<div class="cartes-bureau">'+reprendre+"</div>":"")+'<section class="pile" aria-labelledby="pour-qui"><h2 id="pour-qui">Ce que tu y trouves</h2><div class="cartes-bureau">'+POUR_QUI.map(([s,t,p])=>carte(echap(s),echap(t),"<p>"+echap(p)+"</p>")).join("")+'</div></section><section class="transparence" aria-labelledby="jamais"><h2 id="jamais">Ce que le site ne fera jamais</h2><ul class="liste-nue pile ecart-1-5">'+JAMAIS.map(t=>'<li><span class="non" aria-hidden="true">✗</span> '+echap(t)+"</li>").join("")+'</ul><p class="discret"><a href="'+lien("confidentialite.html")+'">Données et confidentialité</a> : ce que le site garde, où, et qui le voit.</p></section>'+carte("Pendant le test","Un compte, sur invitation","<p>"+echap(COMPTES_DU_TEST)+"</p><p>"+echap(SANS_COMPTE)+"</p>"+seConnecter())+`<section class="pile" id="matieres" aria-labelledby="commencer"><h2 id="commencer">Commencer un cours, sans compte</h2><p class="discret">Choisis une matière : ses portes d'entrée — par chapitre, par thème, pour un contrôle, par la méthode, par la carte des notions, par les labos — mènent toutes au même contenu.</p><div class="matieres-bureau">`+matieres+"</div></section></div>"}var ESPACES={prof:{tete:["Espace professeur","Ce que le site offre aux professeurs","Proposer du travail à ses élèves, voir ce qu’ils réussissent seuls, et les laisser chercher."],corps:()=>'<div class="colonnes">'+carte("Ta classe","Un lien, et les élèves choisissent","<p>Tu crées une classe ; elle a un lien et un code. Un élève qui l'ouvre voit qui l'invite et ce que tu verras de lui, puis confirme. Il peut la quitter quand il veut, et il ne voit rien des autres élèves.</p>")+carte("Le carnet","Cinq envois, aucun texte libre","<p>Un exercice, une partie du cours, une échéance, un devoir composé dans la banque, ou un message choisi dans une liste écrite à l'avance. Rien d'autre ne passe : c'est ce qui rend le carnet sûr pour des mineurs, et lisible par leurs parents.</p>")+carte("La banque d'exercices","Composer un devoir ou une planche",'<p>Tu pioches dans les exercices corrigés de tous les chapitres, par notion, par difficulté, par durée, et tu obtiens un devoir à envoyer ou une planche A4 à imprimer.</p><p><a href="'+lien("guide.html")+`">Le mode d'emploi pour l'enseignant</a></p>`)+'<section class="transparence"><h2>Ce que tu vois de tes élèves</h2><ul class="liste-nue pile ecart-1-5"><li><span class="oui" aria-hidden="true">✓</span> les élèves qui ont rejoint ta classe, par leur identifiant</li><li><span class="oui" aria-hidden="true">✓</span> leurs essais dans ta matière, la part réussie sans aide, leurs jours actifs</li><li><span class="non" aria-hidden="true">✗</span> aucune note, aucun classement, aucune moyenne de classe</li><li><span class="non" aria-hidden="true">✗</span> ni leurs réponses détaillées, ni leurs échanges avec le tuteur</li></ul><p class="discret">Tes élèves voient, de leur côté, ce que tu vois d’eux.</p></section></div>'+carte("Pendant le test","Un compte enseignant","<p>Un compte enseignant est vérifié par l'équipe avant d'ouvrir une classe : tout de suite avec une adresse académique, à la main sinon. "+echap(COMPTES_DU_TEST.replace(/ Un élève.*$/,""))+"</p>"+seConnecter())},parent:{tete:["Espace parent","Ce que le site offre aux parents","Suivre sans surveiller : le temps, la progression, les échéances, et des conseils pour accompagner sans faire à la place."],corps:()=>'<div class="colonnes"><section class="transparence"><h2>Ce que tu vois de ton enfant</h2><ul class="liste-nue pile ecart-1-5"><li><span class="oui" aria-hidden="true">✓</span> son temps de travail et ses jours actifs</li><li><span class="oui" aria-hidden="true">✓</span> par matière, ce qu’il réussit seul ou avec de l’aide</li><li><span class="oui" aria-hidden="true">✓</span> tout son carnet des professeurs, en lecture</li><li><span class="non" aria-hidden="true">✗</span> ses réponses détaillées</li><li><span class="non" aria-hidden="true">✗</span> ses échanges avec le tuteur</li><li><span class="non" aria-hidden="true">✗</span> ses brouillons</li></ul><p class="discret">Ton enfant voit, de son côté, ce que tu vois de lui.</p></section>'+carte("Tes réglages","L'IA du tuteur, le résumé du dimanche","<p>Tu peux couper l'IA du tuteur : ton enfant le voit sur l'interrupteur, avec l'explication. Si tu le veux, un résumé de sa semaine part le dimanche à ton adresse.</p>")+carte("Le compte de ton enfant","Lié au tien, et à lui","<p>Ton enfant t'invite depuis son compte, ou tu crées le sien depuis le tien. Avant 15 ans, ton accord et le sien sont demandés avant que sa progression soit enregistrée en ligne ; d'ici là, elle reste sur son appareil.</p>")+"</div>"+carte("Pendant le test","Un compte parent","<p>"+echap(COMPTES_DU_TEST)+"</p>"+seConnecter())},carnet:{tete:["Carnet des professeurs","Ce que tes professeurs te proposent","Une rubrique par professeur : les échéances, les exercices conseillés, les points de cours à revoir. Rien des autres élèves, jamais de note."],corps:()=>'<div class="colonnes">'+carte("Comment ça marche","Un lien de classe, et ton accord","<p>Un professeur te donne un lien ou un code. Tu vois qui t'invite et ce qu'il verra de toi, puis tu confirmes : rien ne se passe sans ce clic, et tu peux quitter sa classe quand tu veux.</p>")+carte("Ce qui arrive","Des propositions, pas des ordres","<p>Un exercice conseillé, une partie du cours à revoir, une échéance, un devoir, ou un mot d'encouragement choisi dans une liste. Tu coches ce que tu as fait. Tes parents lisent le même carnet.</p>")+"</div>"+carte("Pour le recevoir","Il faut un compte","<p>"+echap(SANS_COMPTE)+"</p>"+seConnecter())}};function presenterEspace(body,m,quoi){let e=ESPACES[quoi];e&&(tete(body,...e.tete),m.innerHTML='<div class="pile ecart-5 presentation">'+e.corps()+"</div>")}function compteVisiteurHTML(){return carte("Avec un compte","Ton travail te suit",liste([oui("ta progression, tes succès et ton bureau, d'un appareil à l'autre"),oui("le carnet de tes professeurs, quand tu rejoins leur classe"),oui("un parent qui suit ton travail, si tu l’invites"),non("ni note, ni classement, ni publicité")])+"<p>"+echap(COMPTES_DU_TEST)+"</p>"+seConnecter())+carte("Sans compte","Tout reste dans ce navigateur","<p>"+echap(SANS_COMPTE)+" Tu peux tout télécharger ou tout effacer, plus bas.</p>")}export{lienConnexion,tete,presenterAccueil,presenterEspace,compteVisiteurHTML};
